"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["21493"],{27442(e){e.exports=JSON.parse('{"id":"FIN-1061","slug":"going-concern-warning","term":"Going-Concern Warning","also_known_as":[],"difficulty":"Advanced","definition":"A going-concern warning is a statement, made by management or by the auditor, that there is significant doubt about a company\'s ability to continue operating for the foreseeable future, usually at least the next twelve months.","explanation":["Financial statements are normally prepared on the assumption that a company will continue in business. When events or conditions cast significant doubt on this, such as heavy losses, debts due that cannot be refinanced, breached loan covenants or loss of a major customer, management must disclose the uncertainty.","Auditors assess whether management\'s going-concern assessment is reasonable. If significant doubt exists and is properly disclosed, the auditor\'s report includes a section highlighting a material uncertainty related to going concern. This is often described as a going-concern warning.","For example, a retailer with falling sales and a large loan due in six months, with no agreed refinancing, might include a note explaining the uncertainty, and its auditor would draw attention to it.","A going-concern warning is a serious signal, but not a prediction of failure. Some companies recover through refinancing, asset sales or new investment. Others fail. The warning can itself make suppliers and lenders more cautious, adding to the pressure on the company."],"note":"","total":1500,"prev":{"slug":"going-concern-value","term":"Going-Concern Value"},"next":{"slug":"going-private","term":"Going Private"}}')}}]);